mapper.select:

WHERE d.knowledge_base_id = #{kbId} AND d.deleted = false
ORDER BY d.id
LIMIT #{limit}
OFFSET #{offset}

SELECT id, document_id, document_version, task_type, status, retry_count, error_code, error_message,
started_at, finished_at, created_at, updated_at, stage, attempt_count, auto_retry_count, next_attempt_at,
lease_expires_at
FROM document_index_task
WHERE document_id = #{id}
ORDER BY id DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT object_key
FROM document_version
WHERE document_id = #{id} AND version_no = #{version}

SELECT count(*)
FROM document_index_task
WHERE document_id = #{id}

SELECT source_format
FROM document_version
WHERE document_id=#{id} AND version_no=#{version}

SELECT name
FROM document_version
WHERE document_id = #{id} AND version_no = #{version}
